-- Supplier and purchase ledger schema.
begin;
create table if not exists public.inventory_suppliers (id uuid primary key default gen_random_uuid(), name text not null check(length(trim(name))>0), contact_name text not null default '', phone text not null default '', email text not null default '', address text not null default '', tax_number text not null default '', notes text not null default '', is_active boolean not null default true, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create unique index if not exists inventory_suppliers_name_lower_uq on public.inventory_suppliers(lower(trim(name)));
create table if not exists public.inventory_purchases (id uuid primary key default gen_random_uuid(), purchase_number bigint generated by default as identity unique, supplier_id uuid not null references public.inventory_suppliers(id) on delete restrict, invoice_number text not null default '', purchase_date date not null default current_date, status text not null default 'received' check(status in ('received','voided')), subtotal numeric(14,2) not null default 0 check(subtotal>=0), discount_amount numeric(14,2) not null default 0 check(discount_amount>=0), shipping_amount numeric(14,2) not null default 0 check(shipping_amount>=0), total_amount numeric(14,2) not null default 0 check(total_amount>=0), paid_amount numeric(14,2) not null default 0 check(paid_amount>=0), payment_status text not null default 'unpaid' check(payment_status in ('unpaid','partial','paid')), notes text not null default '', created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(paid_amount<=total_amount));
create index if not exists inventory_purchases_supplier_date_idx on public.inventory_purchases(supplier_id,purchase_date desc);
create table if not exists public.inventory_purchase_items (id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.inventory_purchases(id) on delete cascade, material_id uuid not null references public.inventory_materials(id) on delete restrict, quantity numeric(14,3) not null check(quantity>0), unit_cost numeric(14,2) not null check(unit_cost>=0), line_total numeric(14,2) generated always as (round(quantity*unit_cost,2)) stored, created_at timestamptz not null default now());
create index if not exists inventory_purchase_items_purchase_idx on public.inventory_purchase_items(purchase_id);
create index if not exists inventory_purchase_items_material_idx on public.inventory_purchase_items(material_id,created_at desc);
alter table public.inventory_suppliers enable row level security;
alter table public.inventory_purchases enable row level security;
alter table public.inventory_purchase_items enable row level security;
drop policy if exists inventory_suppliers_admin_all on public.inventory_suppliers;
create policy inventory_suppliers_admin_all on public.inventory_suppliers for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists inventory_purchases_admin_all on public.inventory_purchases;
create policy inventory_purchases_admin_all on public.inventory_purchases for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists inventory_purchase_items_admin_all on public.inventory_purchase_items;
create policy inventory_purchase_items_admin_all on public.inventory_purchase_items for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
grant select,insert,update,delete on public.inventory_suppliers, public.inventory_purchases, public.inventory_purchase_items to authenticated;
grant usage,select on all sequences in schema public to authenticated;
commit;
